/*
	CREATE DATABASE museo;
	SELECT museo;
	
//	Creación de la base de datos "museo"



//Tabla de los eventos

CREATE TABLE eventos(
	id INT PRIMARY KEY AUTO_INCREMENT,
	nombre VARCHAR(100) NOT null,
	anio INT NOT null,
	imagen_1 VARCHAR(255) NOT NULL,
	imagen_2 VARCHAR(255) NULL,
	imagen_3 VARCHAR(255) NULL,
	descripcion_corta TEXT NOT NULL,
	descripcion_larga TEXT NOT NULL,
	creado TIMESTAMP
);
	
	

INSERT INTO eventos (nombre, anio, imagen_1, imagen_2, imagen_3, descripcion_corta, descripcion_larga)
VALUES ("Primer Ferrocarril de Pasajeros Liverpool-Manchester", 1830,"algunaimagen","","",
"Se inaguró en Inglaterra el primer ferrocarril de pasajeros del mundo, un acontecimiento que marcó el inicio de una revolución de los transportes", 
"La posibilidad de trasladar personas y mercancías de forma más rápida impulsó el crecimiento económico y urbano en numerosos países. Este avance tecnológico sería fundamental décadas después para el desarrollo ferroviario argentino y la llegada del tren al Alto Valle."),

("Ordenanza de Profilaxis Social en Buenos Aires",1875,"algunaimagen","","",
"El Reglamento de la Prostitución aprobado en Buenos Aires el 5 de enero de 1875 legalizó y reglamentó los prostíbulos bajo control médico y policial para frenar las enfermedades venéreas.",
"La ordenanza regulaba aspectos sanitarios vinculados al ejercicio de la prostitución en Argentina (legalización de burdeles, controles sanitarios, administración femenina, registro e impuestos). Este antecedente permite comprender las futuras reglamentaciones que se aplicarían en Cipolletti durante las primeras décadas del siglo XX."),

("Construcción d el Fuerte Confluencia", 1879,"algunaimagen","","",
"El Ejército Argentino construyó el Fuerte Confluencia en la zona donde confluyen los ríos Neuquén y Limay.",
"Este puesto militar formó parte del proceso de ocupación y organización territorial de la Patagonia. Aunque tuvo una existencia relativamente breve, es considerado uno de los antecedentes históricos más importantes para el posterior surgimiento de Cipolletti y otras localidades del Alto Valle."),

("Tendido telegráfico por la región",1881,"algunaimagen","","",
"Se realizó el tendido telegráfico que atravesaba la zona donde posteriormente se desarrollaría Cipolletti.",
"El telégrafo fue una de las innovaciones tecnológicas más importantes del siglo XIX, ya que permitía transmitir mensajes a grandes distancias en cuestión de minutos. Su instalación ayudó a integrar la Patagonia con el resto del país y facilitó la comunicación entre autoridades, comerciantes y pobladores."),

("Obra para el funcionamiento del teléfono.",1883,"algunaimagen","","",
"Se completó la obra del edificio destinado al funcionamiento del teléfono del tercer fortín.",
"Esta infraestructura era necesaria para asegurar el correcto funcionamiento de las comunicaciones en una región que todavía estaba en proceso de organización y poblamiento."),

("Manuel Fernández Oro compra las tierras",1886,"algunaimagen","","",
"El general Manuel Fernández Oro adquirió importantes extensiones de tierra en la región.",
" Esta compra resultó decisiva para el futuro desarrollo de la Colonia Lucinda y de la ciudad de Cipolletti. Fernández Oro impulsó proyectos de colonización, agricultura y urbanización que transformaron profundamente la zona."),

("Primer Juzgado de Paz del Alto Valle",1888,"algunaimagen","","",
"Se estableció en General Roca el primer Juzgado de Paz del Alto Valle.",
"Esta institución fue fundamental para la organización legal y administrativa de una región que comenzaba a recibir nuevos pobladores. Los juzgados de paz se encargaban de registrar hechos civiles y resolver conflictos cotidianos de la comunidad."); 

("Llegada de José Delfino",1898,"algunaimagen","","",
"José Delfino llegó a la región para trabajar en la construcción del ferrocarril.",
"Con el tiempo se transformó en una figura destacada del desarrollo comercial local. Su familia participó activamente en emprendimientos que acompañaron el crecimiento de Cipolletti, especialmente a través del Hotel Argentino."),

("Llegada del ferrocarril a la región",1899,"algunaimagen","","",
"La llegada del tren representó uno de los acontecimientos más importantes para el desarrollo del Alto Valle.",
"El tren llegó a la región con la inauguración del ramal en Chelforo el 30 de mayo de 1899, acompañado de un banquete en Chimpay. Nuestra estación se denominó sucesivamente Km 1240, Km 1190, Parada o Estación Limay, hasta quedar definitivamente como Estación Cipolletti. El ferrocarril permitió transportar personas, productos agrícolas y materiales de construcción, favoreciendo el crecimiento económico y poblacional. Gracias a esta conexión, la región pudo integrarse de manera más efectiva al resto del país."),

("Inundaciones de marzo",1899,"algunaimagen","","",
"Fuertes inundaciones destruyeron plantaciones, animales, cultivos y el molino. El resultado fue la quiebra y posterior venta de las tierras al general Fernández Oro. En la zona sur de Cipolletti, lo que hoy conocemos como el barrio La Braña.",
"Fuertes inundaciones destruyeron plantaciones, animales, cultivos y el molino. El resultado fue la quiebra y posterior venta de las tierras al general Fernández Oro. En la zona sur de Cipolletti, lo que hoy conocemos como el barrio La Braña. Finalizada la Conquista del Desierto, las tierras de La Confluencia fueron asignadas a la empresa La Vitivinícola Sanjuanina, que aportó divisas para su concreción. Allí comenzó la colonia con asentamientos de personas, animales y cultivos. Incluso se instaló un molino harinero, movido por una noria que tomaba impulso a través del canal de Furque —hoy canal de los Milicos—, que extraía agua del río Neuquén a 200 metros río abajo del actual tercer puente. En marzo de 1899, inundaciones arrasaron con plantaciones, animales, cultivos y el molino. El resultado fue la quiebra y posterior venta de las tierras al general Fernández Oro. Este escenario ocurrió en la zona sur de lo que hoy conocemos como Cipolletti, en el barrio Labraña "),

("César Cipolletti entrega el estudio de irrigación",1899,"algunaimagen","","",
"El ingeniero italiano César Cipolletti presentó los estudios para la irrigación de los ríos Negro y Colorado.Allí señalaba: “En cuanto al agua, la hay suficiente para regar más de un millón de hectáreas, es decir, más de la mitad de todo Egipto con el Nilo”.",
"El ingeniero italiano César Cipolletti presentó los estudios para la irrigación de los ríos Negro y Colorado.Allí señalaba: “En cuanto al agua, la hay suficiente para regar más de un millón de hectáreas, es decir, más de la mitad de todo Egipto con el Nilo”. El sueño de Cipolletti era ejecutar obras de riego en el valle superior del río Negro y posibilitar el asentamiento de colonias agrícolas. Como sugerencia imperativa, pedía la instalación de una estación meteorológica para caracterizar el clima y obtener registros diarios de los ríos Neuquén, Limay y Negro."),

("Habilitación del telégrafo ferroviario para uso público",1899,"algunaimagen","","",
"El servicio telegráfico vinculado al ferrocarril comenzó a estar disponible para los habitantes de la región.",
"El servicio telegráfico vinculado al ferrocarril comenzó a estar disponible para los habitantes de la región, cuando el fortín fue trasladado a un nuevo edificio cercano a Fernández Oro. Allí quedó instalado el telégrafo con su telegrafista, y posteriormente se anexó el servicio de correo. Esto permitió una comunicación más rápida con otras localidades y facilitó el intercambio comercial y administrativo."),

("Ferrocarril y crecimiento de la prostitución",1901,"algunaimagen","","",
"El aumento de trabajadores, viajeros y población masculina vinculada al trabajo rural y construcción, se promovió la prostitución como medio de estabilización social, bajo la idea de que cada pueblo debía contar con un prostíbulo.",
"El aumento de trabajadores, viajeros y población masculina vinculada al trabajo rural y construcción, se promovió la prostitución como medio de estabilización social, bajo la idea de que cada pueblo debía contar con un prostíbulo, siempre bajo la condición legal de contar con un médico responsable del control sanitario. En Cipolletti, el primer prostíbulo documentado fue el de Juana Bordegaray, conocido como “La casa rosada”, ubicado en la actual calle Rivadavia. También existieron los de Juana Rodríguez y María Esther Romero, junto a casos independientes."),

("Fundación Hotel Argentino",1902,"algunaimagen","","",
"Enrique Delfino recibió un terreno del General Fernández Oro y decidió trasladar su fonda al centro del pueblo. Construyó habitaciones y salones.",
"Enrique Delfino recibió un terreno del General Fernández Oro y decidió trasladar su fonda al centro del pueblo. Construyó habitaciones y salones. El Hotel Argentino se encuentra ubicado en la calle Fernández Oro, frente al número 120, donde anteriormente se encontraba la estación de ferrocarril. Don José Delfino llegó a la zona en 1898 para trabajar en la construcción del ferrocarril y se instaló en la margen izquierda del río Neuquén con un negocio llamado 'El Boliche'."),

("Fundación de Cipolletti",1903,"algunaimagen","","",
"El 3 de octubre de 1903 se considera la fecha oficial de fundación de Cipolletti.",
"El 3 de octubre de 1903 se considera la fecha oficial de fundación de Cipolletti. La ciudad de Cipolletti, ubicada en Río Negro, se fundó el 3 de octubre de 1903 por el general Manuel Fernández Oro, quien loteo las tierras en la confluencia de los ríos Limay y Neuquén, y creció alrededor del obrador ferroviario. Su nombre honra al ingeniero César Cipolletti."),

("Venta de los primeros terrenos urbanos",1903,"algunaimagen","","",
"Se anunciaron los lotes urbanos y comenzaron a venderse los primeros terrenos.",
"Se anunciaron los lotes urbanos y comenzaron a venderse los primeros terrenos de la nueva localidad. Esta medida favoreció la llegada de familias, comerciantes y emprendedores que participaron en la construcción de la futura ciudad."),

("Habilitación del apeadero ferroviario",1904,"algunaimagen","","",
"Se habilitó el apeadero u obrador ferroviario, infraestructura fundamental para el funcionamiento del tren en la zona.",
"Se habilitó el apeadero u obrador ferroviario, infraestructura fundamental para el funcionamiento del tren en la zona. Alrededor de este espacio comenzaron a desarrollarse actividades comerciales y de servicios que impulsaron el crecimiento urbano de Cipolletti."),

("Primeras exhibiciones de cine en el Hotel Argentino",1904,"algunaimagen","","",
"Los hermanos Sianca comenzaron a proyectar películas en el Hotel Argentino.",
"Los hermanos Sianca comenzaron a proyectar películas en el Hotel Argentino. Estas funciones constituyeron una de las primeras experiencias cinematográficas de la ciudad y representaron un importante acontecimiento cultural para los habitantes de la época."),

("Fallecimiento de César Cipolletti",1908,"algunaimagen","","",
"El ingeniero César Cipolletti murió cerca de las Islas Canarias.",
"El ingeniero César Cipolletti murió cerca de las Islas Canarias. Tras terminar los estudios hidráulicos, Cipolletti retornó a Italia y brindó una conferencia en el Aula Magna del Colegio Romano, en Roma, ante soberanos y personalidades de la banca y el comercio. Buscaba interesar a un consorcio bancario para que, junto con los gobiernos de Italia y Argentina y la empresa del Ferrocarril Sud, se realizarán los trabajos proyectados y se colonizaran las tierras. Sin embargo, no tuvo la fortuna de encontrar el apoyo político necesario. Igualmente, el gobierno argentino lo convocó nuevamente para desarrollar su propio plan, cercano a la regulación de aguas y la canalización a través del Dique Cordero/Ballester. Pero el 23 de enero de 1908, la muerte lo sorprendió."),

("Juan Ramos a cargo de la Comisaría Limay",1909,"algunaimagen","","",
"Juan Ramos asumió responsabilidades en la Comisaría Limay.",
"Juan Ramos asumió responsabilidades en la Comisaría Limay. El primer destacamento se ubicó en la esquina de Fernández Oro y Belgrano. Un segundo lugar fue en Fernández Oro, esquina Italia; más tarde, en Irigoyen 580 y posteriormente en Miguel Muñoz y San Martín. Hoy la policía se encuentra ubicada en un edificio propio sobre la calle Roca, con el destacamento del barrio Don Bosco."),

("Continuidad de los proyectos del Dique Ballester",1909,"algunaimagen","","",
"Se propuso continuar los proyectos relacionados con el futuro Dique Ingeniero Ballester.",
"Se propuso continuar los proyectos relacionados con el futuro Dique Ingeniero Ballester. El Ing. Julián Romero (director de Irrigación) propuso designar al Ing. Desio Severini como director de la obra, ratificado por decreto ministerial y secundado por el Ing. Cantuti. Su objetivo era concretar los principales sueños del difunto Ing. Cipolletti. Estas iniciativas buscaban regular el agua de los ríos y garantizar el suministro necesario para el desarrollo agrícola del Alto Valle."),

("Creación del Juzgado de Paz y Registro Civil",1910,"algunaimagen","","",
"El 10 de marzo se creó oficialmente el Juzgado de Paz y Registro Civil de Cipolletti.",
"El 10 de marzo se creó oficialmente el Juzgado de Paz y Registro Civil de Cipolletti. El primer juez de Paz en Cipolletti fue Luis Maillet. En 1910, se registraron 57 nacimientos, 8 matrimonios y 34 defunciones. Esta institución permitió registrar nacimientos, matrimonios y defunciones, además de atender cuestiones legales básicas de la comunidad."),

("Primer nacimiento registrado: Catalina Dávila",1910,"algunaimagen","","",
"Catalina Dávila fue la primera persona registrada oficialmente en el Registro Civil de Cipolletti.",
"Catalina Dávila fue la primera persona registrada oficialmente en el Registro Civil de Cipolletti. Este hecho simboliza el comienzo de los registros civiles de la ciudad y constituye un dato histórico de gran valor."),

("Inicio de las obras del Dique Ingeniero Ballester",1910,"algunaimagen","","",
"Las obras del puente-dique comenzaron en enero de 1910.",
"Las obras del puente-dique comenzaron en enero de 1910. El ramal ferroviario desde Parada Limay (actual Cipolletti) hasta Barda del Medio permitió el traslado de materiales y personal. El diseño inicial contemplaba 12 vanos con 7 compuertas de 20 m de ancho y 4 m de altura, accionadas por electromotores El dique permitió regular el agua destinada al riego y fue clave para el desarrollo agrícola y económico del Alto Valle."),

("Llegada de Bernardo Jorge Hercig al Valle",1910,"algunaimagen","","",
"Bernardo Jorge Hercig llegó al Alto Valle y posteriormente su familia se vincularía al desarrollo de la histórica Bodega La Falda.",
"Bernardo Jorge Hercig llegó al Alto Valle y posteriormente su familia se vincularía al desarrollo de la histórica Bodega La Falda. Adquirió tierras a Alberto Peusser, en la zona de las antiguas caballerizas de la mansión, e instaló allí su emprendimiento vitivinícola, convirtiéndose en una de las primeras bodegas del Alto Valle. El nombre “La Falda” surgió como una adaptación del nombre de su ciudad natal, Fulda. Actualmente funciona como museo, restaurante y salón de eventos, administrado por descendientes de su fundador, don Bernardo Jorge Hercig.  Su presencia forma parte de la historia de las familias inmigrantes que contribuyeron al crecimiento económico de la región."),

("Reforma del Hotel Argentino",1910,"algunaimagen","","",
"Enrique Delfino realizó importantes mejoras en el Hotel Argentino.",
"Enrique Delfino realizó importantes mejoras en el Hotel Argentino. Delfino realizó una reforma definitiva, agregando habitaciones con baño y piso con agua caliente .Este establecimiento era uno de los principales centros sociales y comerciales de la localidad, utilizado por viajeros, comerciantes y vecinos."),

("Llegada de Alberto Peusser",1911,"algunaimagen","","","Alberto Peusser llegó a la región y adquirió aproximadamente 300 hectáreas.",
"Alberto Peusser llegó a la región y adquirió aproximadamente 300 hectáreas. Procedente de Buenos Aires, invitado por Don Manuel Cordiviola, pionero del Alto Valle.  Allí desarrolló una importante explotación agrícola y construyó la conocida Mansión Peusser, una de las residencias más destacadas de la historia local. Una mansión réplica del Petit Trianon de Madame Pompadour, en Francia, de estilo neoclásico con materiales, en gran parte importados, que llegaron desde Bahía Blanca. La residencia contaba con calefacción central, la primera en el Alto Valle."),

("Crecida del río Neuquén",1911,"algunaimagen","","","Una gran crecida afectó las obras del Dique Ballester.",
"Una gran crecida afectó las obras del Dique Ballester. La construcción del canal principal avanzó lentamente y quedó inconclusa durante 8 años, debido a la gran crecida del Neuquén en 1911 y a la Primera Guerra Mundial (1914-1918)  demostrando las dificultades que implicaba controlar los recursos hídricos de la región. A pesar de los daños, los trabajos continuaron debido a la importancia estratégica del proyecto."),

("Primeros registros del Cipolletti Athletic Club",1912,"algunaimagen","","","Aparecen los primeros antecedentes del Cipolletti Athletic Club",
"Aparecen los primeros antecedentes del Cipolletti Athletic Club, institución que con el tiempo se transformaría en el actual Club Cipolletti, uno de los símbolos deportivos más importantes de la ciudad. Desde sus inicios, adoptó los colores negro y blanco, que mantiene hasta la actualidad."),

("Llegada del Padre José María Brentana",1914,"algunaimagen","","","El sacerdote José María Brentana llegó a la comunidad cipoleña.",
"El sacerdote José María Brentana llegó a la comunidad cipoleña, y la ciudad contaba con 700 habitantes. El primer sitio destinado al culto católico fue una pequeña habitación en la calle Villegas. Luego, se trasladó a otro inmueble cedido por el General Fernández Oro. El Sr. José de lasa donó la manzana donde se encuentra hoy la capilla, y la obra de construcción fue realizada por Don Jacinto del Ben con planos del Ingeniero Bence."),

("Ampliación de la capacidad del dique", 1915,"algunaimagen","","","Se realizaron mejoras para aumentar la capacidad del Dique Ingeniero Ballester",
"Se realizaron mejoras para aumentar la capacidad del Dique Ingeniero Ballester, El dique fue construido para erogar 3.500 m³, ampliados a 5.000 m³. Trabajaron aproximadamente 350 obreros de distintas especialidades."),

("Crónica de un baile",1916,"algunaimagen","","","En 1916, el 9 de marzo, el periódico local publicaba la siguiente crónica: “Ayer tuvo lugar un baile en la casa del señor Alberto Lizarraga.",
"En 1916, el 9 de marzo, el periódico local publicaba la siguiente crónica: “Ayer tuvo lugar un baile en la casa del señor Alberto Lizarraga, que duró hasta las tres de la madrugada. Se mencionaron los nombres de los asistentes y se destacó la animación de la velada.” Desde 1911 en adelante, en el predio de la mansión Peuser, cuyas escalinatas daban al Salón de los Espejos —réplica del de Versalles, en el edificio neoclásico del Petit Trianon—, se celebraban veladas musicales en Colonia Lucinda, hoy Cipolletti."),

("Fundación de La Mayorina",1917,"algunaimagen","","","Adolfo Mengelle adquirió tierras en Colonia Lucinda y fundó La Mayorina.",
"Adolfo Mengelle adquirió tierras en Colonia Lucinda y fundó La Mayorina. Adquirió un lote de hectáreas en Colonia Lucinda, donde fundó su establecimiento “La Mayorina”, nombre elegido en honor a su esposa. En el lugar plantó frutales e instaló bodegas debido a la gran extensión de viñedos, además de un secadero de frutas. Sobre la actual Ruta 151, pasando Cuatro Esquinas, construyó un complejo de edificios que incluía bodega, galpón de empaque, oficinas administrativas, viviendas para peones, carpintería y herrería."),

("Carlos Reyna integra la primera Comisión de Fomento",1919,"algunaimagen","","","El médico Carlos Reyna participó en la primera Comisión de Fomento de Cipolletti. Además de su trabajo profesional en el área de la salud, tuvo una activa participación en la organización institucional de la ciudad.",
"El médico Carlos Reyna participó en la primera Comisión de Fomento de Cipolletti. Además de su trabajo profesional en el área de la salud, tuvo una activa participación en la organización institucional de la ciudad. Carlos María Reyna, junto a su esposa Haydée Soracco, emprendieron su viaje desde Mercedes (Buenos Aires) hacia el Territorio Nacional de Río Negro. Se instaló en la Colonia Lucinda (actual barrio El Trabajo), más precisamente donde hoy se ubica la iglesia. Este fue probablemente el primer médico de Cipolletti. Estableció relaciones que lo llevaron a ser nominado en 1919 por el gobernador Evrat como parte de la primera Comisión de Fomento de la colonia."),

("Ordenanza Nº 1 sobre prostitución",1919,"algunaimagen","","","Se dictó la primera ordenanza local relacionada con la prostitución.",
"Se dictó la primera ordenanza local relacionada con la prostitución. La Comisión de Fomento dictó en 1919 la Ordenanza Nº 1, que regulaba la actividad imponiendo tasas para la inscripción de prostitutas, la expedición de libretas de sanidad, las revisiones médicas periódicas y los cambios de domicilio."),

("Alberto Jordán se instala en la zona",1920,"algunaimagen","","","Alberto Jordán se estableció en el área que posteriormente sería conocida como Isla Jordán.",
"Alberto Jordán se estableció en el área que posteriormente sería conocida como Isla Jordán. Se casó con Ema Quintana, con quien tuvo tres hijos. Trabajó desmontando tierras, cultivando alfalfa, frutales y huertas. Criaba animales y se dedicaba además al negocio del ripio, que transportaba en carretas hasta la actual ruta 22. Su presencia quedó profundamente vinculada a la historia de este importante espacio natural y recreativo de la ciudad."),

("Creación de la Sociedad de Socorros Mutuos Española",1920,"algunaimagen","","","El 12 de diciembre de 1920, se reunieron en Cipolletti un grupo de españoles decididos a crear una Sociedad de Socorros Mutuos.",
"El 12 de diciembre de 1920, se reunieron en Cipolletti un grupo de españoles decididos a crear una Sociedad de Socorros Mutuos. Diez días más tarde, una asamblea aprobó los estatutos y eligió por votación al primer Consejo Directivo de la Asociación de Socorros Mutuos y Cultural de Cipolletti La comunidad española fundó esta institución con el objetivo de brindar ayuda mutua a sus integrantes. Con el paso de los años se convirtió en una de las entidades sociales y culturales más importantes de Cipolletti."),

("Carlos Reyna abandona Cipolletti",1920,"algunaimagen","","","Tras años de trabajo profesional y participación institucional, Carlos Reyna dejó la ciudad.",
"Tras años de trabajo profesional y participación institucional, Carlos Reyna dejó la ciudad. Desanimado tras su paso por la función pública ad honorem y afectado por una parálisis debido a una inyección mal aplicada, abandonó Cipolletti en silla de ruedas. Falleció el 10 de mayo de 1967 a los 77 años. Su figura quedó asociada a los primeros años de la medicina y la organización comunitaria local.");



('Primera experiencia de iluminación eléctrica', 1921, 'algunaimagen.jpg', '', '', 'Se realizó una prueba de iluminación eléctrica en el Prado Español.', 'Se realizó una prueba de iluminación eléctrica en el Prado Español. Este acontecimiento representó un importante avance tecnológico para la ciudad y anticipó la llegada definitiva del servicio eléctrico. El dueño de la usina y de las redes era el Sr. Enrique Schreiber, de origen alemán. Junto con su hijo realizó todos los trabajos de instalación. La empresa se llamaba “Luz y Fuerza Eléctrica” y estaba ubicada en las calles 9 de Julio y Belgrano. Más adelante pasó a manos de Agua y Energía.'),
('Fundación de la Escuela Nº 53 Bernardino Rivadavia', 1922, 'algunaimagen.jpg', '', '', 'El 24 de abril se fundó la Escuela Nº 53', 'El 24 de abril se fundó la Escuela Nº 53 una de las instituciones educativas más importantes de la historia de Cipolletti. En sus inicios, la Escuela Nº 53 compartía edificio con la Escuela Nº 33, en una antigua construcción —hoy inexistente— ubicada sobre calle Hipólito Yrigoyen, casi esquina Italia. Durante el turno mañana funcionaba la Escuela 53 y, por la tarde, la Escuela 33. Esta situación se mantuvo hasta 1952, año en que se otorgó el terreno de la manzana completa para la nueva sede.'),
('Piedra fundamental de la Capilla Histórica', 1923, 'algunaimagen.jpg', '', '', 'Se colocó la piedra fundamental de la Capilla Histórica', 'Se colocó la piedra fundamental de la Capilla Histórica pero debido a su reducido tamaño, se vendió para recaudar fondos. La piedra fundamental se perdió. La obra fue impulsada por la comunidad local y por el Padre Brentana.'),
('Inauguración oficial de la electricidad', 1923, 'algunaimagen.jpg', '', '', 'El 1 de junio se inauguró oficialmente el servicio eléctrico', 'El 1 de junio se inauguró oficialmente el servicio eléctrico en la ciudad, por resolución del gobernador Víctor Molina, quien había autorizado su instalación el 5 de abril de ese mismo año. Cipolletti fue la primera población del Alto Valle en contar con luz eléctrica. La llegada de la electricidad transformó la vida cotidiana, mejoró la actividad comercial y permitió nuevos servicios para la población.'),
('Inauguración del alumbrado público', 1923, 'algunaimagen.jpg', '', '', 'El alumbrado público se inauguró el 25 de mayo de 1923.', 'El alumbrado público se inauguró el 25 de mayo de 1923. En septiembre de ese año, según la Comisión de Fomento, el servicio eléctrico ya se cobraba a 88 clientes entre domicilios y comercios.'),
('Inauguración de la Capilla Histórica', 1924, 'algunaimagen.jpg', '', '', 'Durante este año quedó habilitada la Capilla Histórica de Cipolletti', 'Durante este año quedó habilitada la Capilla Histórica de Cipolletti una de las construcciones religiosas más importantes de la ciudad. La obra fue impulsada por el Padre José María Brentana y por los vecinos de la comunidad. Además de cumplir funciones religiosas, la capilla se convirtió en un punto de encuentro social y cultural para los primeros habitantes de la localidad.'),
('Doctor Juan Lafourcade abre su consultorio', 1924, 'algunaimagen.jpg', '', '', 'En 1924 envió una nota a la Comisión de Fomento de la Estación Cipolletti anunciando la apertura de su consultorio', 'En 1924 envió una nota a la Comisión de Fomento de la Estación Cipolletti anunciando la apertura de su consultorio y ofreciendo sus servicios profesionales. Entre 1925 y 1926 fue mencionado en actas de la Comisión por su intervención en el caso de la Sra. Bordegaray, regente de un prostíbulo sin condiciones de higiene ni construcción. En 1925 fue confirmado como médico municipal con una subvención anual de 500 pesos moneda nacional.'),
('Se creó un Registro de Prostitutas', 1926, 'algunaimagen.jpg', '', '', 'A partir del 1º de junio de 1926 se creó un Registro de Prostitutas', 'A partir del 1º de junio de 1926 se creó un Registro de Prostitutas en el que se anotaron 241 mujeres. El promedio de edad era de 26 años, con una menor de 20 y una mayor de 48. La mayoría eran argentinas (193), pero también había chilenas, italianas, polacas, turcas, españolas, entre otras nacionalidades. Noventa y cinco declararon ser analfabetas.'),
('Formaliza su fundación el Club Cipolletti', 1926, 'algunaimagen.jpg', '', '', 'El 26 de octubre de 1926 se formaliza su fundación', 'El 26 de octubre de 1926 se formaliza su fundación siendo su primer presidente el Dr. Juan Bautista Lafourcade. En 1927 se crea el emblema oficial del club. El equipo de fútbol jugó primero en la segunda división del fútbol argentino, ascendió al Torneo Argentino A y luego a Primera B Nacional, para terminar subiendo a Argentino A donde juega actualmente.'),
('Renuncia el Dr. Lafourcade', 1927, 'algunaimagen.jpg', '', '', 'El 21 de diciembre de 1927 el doctor Lafourcade presentó su renuncia como médico municipal', 'El 21 de diciembre de 1927 el doctor Lafourcade presentó su renuncia como médico municipal ya que se ausentaría definitivamente de la ciudad. Ese mismo día fue nombrado su reemplazo, el doctor Ángel Molteni'),
('Asociación de Socorros Mutuos Il Piave', 1927, 'algunaimagen.jpg', '', '', 'el 1 de mayo de 1927 en una institución llamada Asociación de Socorros Mutuos Il Piave.', 'el 1 de mayo de 1927 en una institución llamada Asociación de Socorros Mutuos Il Piave. La comunidad italiana marcó su presencia con una activa participación en la vida comunitaria, contribuyendo al enriquecimiento cultural y material de la misma. Esta comunidad en Cipolletti se nucleó el 1 de mayo de 1927 en una institución llamada Asociación de Socorros Mutuos Il Piave. La apertura recibió un masivo apoyo de la comunidad, sobre todo hacia las primeras comisiones que se propusieron como objetivo construir una sede social con salón propio'),
('Autorización instalación red de agua', 1932, 'algunaimagen.jpg', '', '', 'Con fecha 11 de mayo de 1932, se habría autorizado a la empresa Usinas Unidas a instalar una red de agua corriente', 'Con fecha 11 de mayo de 1932, se habría autorizado a la empresa Usinas Unidas a instalar una red de agua corriente la cual ese mismo año fue habilitada para uso público.'),
('Sanción Ley 12.331 se prohibieron los prostíbulos a nivel nacional', 1936, 'algunaimagen.jpg', '', '', 'la Ley 12.331 que prohibió los prostíbulos en todo el territorio nacional.', 'la Ley 12.331 que prohibió los prostíbulos en todo el territorio nacional. La prostitución en Cipolletti no fue una práctica clandestina, sino una actividad institucionalizada, controlada y aceptada por las autoridades municipales y provinciales, hasta su declive con la sanción de la Ley 12.331 que prohibió los prostíbulos en todo el territorio nacional.'),
('Sociedad israelita', 1937, 'algunaimagen.jpg', '', '', 'En 1937, algunas familias judías de Cipolletti y Neuquén se reunieron con el propósito de organizarse como comunidad.', 'En 1937, algunas familias judías de Cipolletti y Neuquén se reunieron con el propósito de organizarse como comunidad. Tenían como objetivo aglutinar a los judíos de la zona en un marco religioso, cultural, educativo y social. Alquilaron un pequeño salón en Cipolletti y contrataron a un maestro de hebreo. Luego se edificó la sinagoga. Los trámites se realizaron a través de la Asociación Israelita de General Roca, que ya poseía personería jurídica.'),
('Aparición de Tribuna Cipoleña', 1938, 'algunaimagen.jpg', '', '', 'Comenzó a publicarse Tribuna Cipoleña , uno de los periódicos locales más importantes de la época.', 'Comenzó a publicarse Tribuna Cipoleña , uno de los periódicos locales más importantes de la época. Comenzó a publicarse Tribuna Cipoleña, uno de los periódicos locales más importantes de la época. Este medio permitió difundir noticias sobre política, economía, actividades sociales, educación y acontecimientos cotidianos de la ciudad. En una época donde la radio aún tenía un alcance limitado y no existían los medios digitales, los periódicos eran la principal fuente de información para los vecinos. Gracias a publicaciones como esta hoy es posible conocer numerosos detalles de la historia cipoleña.'),
('Primer gremio docente local', 1940, 'algunaimagen.jpg', '', '', 'Durante 1940 se organizó el primer gremio docente de Cipolletti.', 'Durante 1940 se organizó el primer gremio docente de Cipolletti. La Escuela Nº 53 se inauguró con 10 alumnos, y al finalizar el primer ciclo lectivo ya contaba con 36 estudiantes. Para 1933, la matrícula ascendía a 179 varones y 163 mujeres, distribuidos en diez secciones de grado. Entre sus registros figura la creación del primer gremio docente local. En noviembre de 1940, maestros y maestras de la zona se reunieron en el local de las Escuelas 33 y 53 con el objetivo de fundar un centro que promoviera el mejoramiento profesional y la defensa de los intereses del magisterio. El maestro Romelio M. Lucero fue designado presidente provisional y Blanca E. R. de Basconnet, secretaria. De esa reunión surgió la Declaración de Principios y Propósitos del Centro de Docentes, quedando formalmente constituido'),
('Bodas de Plata de la Sociedad Española', 1940, 'algunaimagen.jpg', '', '', 'La Sociedad Española celebró sus 25 años de existencia', 'La Sociedad Española celebró sus 25 años de existencia mediante actos y festejos que reunieron a gran parte de la comunidad. Se realizó una gran celebración con actos religiosos, homenaje a los fundadores y una medalla de oro al presidente Baldomero Criado, por sus 25 años de trabajo en la Comisión Directiva. También se organizaron comidas y romerías. La institución continúa ayudando a la comunidad española mediante asesoramiento, becas y actividades culturales y deportivas, además de colaborar con la Escuela N.º 191 “Miguel de Unamuno” y prestar su salón gratuitamente a instituciones locales. En 2017, recibió un predio en la Isla Jordán para desarrollar un espacio recreativo. La Asociación representa el esfuerzo de los primeros inmigrantes españoles, quienes se unieron para ayudarse mutuamente y mantener sus tradiciones en Cipolletti.'),
('Autorización definitiva del servicio de agua corriente', 1941, 'algunaimagen.jpg', '', '', 'Finalmente, en el año 1941, se autorizó a Usinas Unidas a instalar el sistema de agua corriente de manera definitiva.', 'Finalmente, en el año 1941, se autorizó a Usinas Unidas a instalar el sistema de agua corriente de manera definitiva. La disponibilidad de agua potable representó una mejora significativa en la calidad de vida de los habitantes, permitiendo mejores condiciones sanitarias y reduciendo riesgos de enfermedades. La obra acompañó el crecimiento urbano de Cipolletti y se transformó en un servicio esencial para la comunidad.'),
('Construcción del Prado Español', 1941, 'algunaimagen.jpg', '', '', 'La Sociedad Española impulsó la construcción del Prado Español', 'La Sociedad Española impulsó la construcción del Prado Español un espacio destinado a actividades recreativas, encuentros familiares, festivales y celebraciones comunitarias. Este lugar se convirtió en uno de los principales centros de reunión social de la ciudad durante varias décadas y fortaleció la integración de los inmigrantes españoles con el resto de la comunidad.'),
('Martín Fabi jefe de correo', 1941, 'algunaimagen.jpg', '', '', 'Martín Fabi asumió la conducción del servicio postal local.', 'Martín Fabi asumió la conducción del servicio postal local. En una época en la que la correspondencia era el principal medio de comunicación a larga distancia, el correo cumplía una función esencial para las familias, las empresas y las instituciones públicas. El correo pasó por varias ubicaciones, comenzó anexado al edificio del telégrafo cerca de Fernández Oro en 1899 y en 1902 se ubicaba en Belgrano 21. La tercera ubicación del correo fue en la calle Miguel Muñoz 44, propiedad de Fernández Oro, quien mandó construir el edificio especialmente para ese fin. El inmueble fue alquilado hasta 1980, año en que se trasladó a la esquina de Mengelle y Teniente Ibáñez, donde permanece hasta hoy.'),
('Construcción de la casa del Parque Rosauer', 1942, 'algunaimagen.jpg', '', '', 'Se construyó una de las edificaciones más representativas vinculadas al actual Parque Rosauer.', 'Se construyó una de las edificaciones más representativas vinculadas al actual Parque Rosauer. El Parque Don Juan Erich Rosauer se ubica en la zona centro de la ciudad y cuenta con una superficie de 4 hectáreas. Fue donado por el General Fernández Oro para la creación de una estación meteorológica. La casa que se encuentra en el centro del parque fue construida en 1942 y actualmente es sede del Club de Jardinería Maipue.'),
('Fuente de Plaza San Martín', 1943, 'algunaimagen.jpg', '', '', 'La plaza cuenta con un mástil donado por Yacimientos Petrolíferos Fiscales, un monumento al General Fernández Oro y una fuente trabajada por Giacomo Bastituzzi en 1943.', 'La plaza cuenta con un mástil donado por Yacimientos Petrolíferos Fiscales, un monumento al General Fernández Oro y una fuente trabajada por Giacomo Bastituzzi en 1943. La Plaza San Martín es un ícono de la ciudad de Cipolletti, ubicada en el centro de la ciudad. Con una superficie de 100x100 metros, es un lugar de encuentro y esparcimiento para los habitantes. La plaza cuenta con un mástil donado por Yacimientos Petrolíferos Fiscales, un monumento al General Fernández Oro y una fuente trabajada por Giacomo Bastituzzi en 1943. La plaza fue trazada por Don Luis Saltevi y plantada por Don Germán Valles bajo la presidencia de Bernardo Herzig. El mástil se encuentra en el centro de la plaza y ha sido escenario de actos escolares y municipales. La casilla para herramientas fue diseñada por Antonio Turrin y construida con la colaboración de Urbano Bertuzzi y Antonio Di Sicco.'),
('Raúl Quadrini conoce a Nelly Giromini', 1944, 'algunaimagen.jpg', '', '', 'En el carnaval de 1944 Raúl Quadrini conoció a Nelly Giromini,', 'En el carnaval de 1944 Raúl Quadrini conoció a Nelly Giromini, En el carnaval de 1944, cuando era practicante en el Hospital de la Società Unione e Benevolenza de Rosario, Raúl Quadrini conoció a Nelly Giromini, gracias a la intervención de amigos en común. Este acontecimiento marcó el inicio de una relación personal importante en la vida del médico Raúl Quadrini, quien años después se transformaría en una de las figuras más destacadas de la medicina cipoleña.'),
('Inundación en Isla Jordán', 1945, 'algunaimagen.jpg', '', '', 'Una crecida en 1945 cubrió', 'Una crecida en 1945 cubrió Originalmente, la Isla Jordán abarcaba 170 hectáreas. Una crecida en 1945 cubrió parte de ellas. Tras la construcción de la represa El Chocón–Cerros Colorados, disminuyeron las crecidas, aunque no desaparecieron. Hoy, su geografía muestra caminos sinuosos, pastos, arbustos, parrillas, juegos infantiles, canchas de fútbol y una pileta municipal (ante la contaminación del río).'),
('Llegada de Pedro Moguillansky', 1946, 'algunaimagen.jpg', '', '', 'Moguillansky llegó a la región en 1946, con apenas 25 años,', 'Moguillansky llegó a la región en 1946, con apenas 25 años, pocos recursos y un título que lo habilitaba a ejercer, pero con gran incertidumbre. Fue testigo de los primeros avances en la zona: análisis de orina, electrocardiogramas, marcapasos, aparición de especialidades médicas. Relata cómo su primer consultorio fue prestado por el Dr. Márquez, quien le enseñó el valor de la medicina preventiva y del compromiso social. Con el tiempo se convertiría en una figura reconocida dentro del ámbito de la salud local, contribuyendo al fortalecimiento de la atención médica en la ciudad.'),
('Nacionalización del servicio eléctrico', 1947, 'algunaimagen.jpg', '', '', 'En febrero de 1947, las instalaciones electricas y el servicio fueron transferidas al Estado Nacional', 'En febrero de 1947, las instalaciones electricas y el servicio fueron transferidas al Estado Nacional En febrero de 1947, las instalaciones electricas y el servicio fueron transferidas de la empresa Usinas Unidas, al Estado Nacional y pasaron a depender de Agua y Energía. Esta medida buscó mejorar la administración y expansión del servicio, acompañando el crecimiento poblacional y económico de Cipolletti.'),
('Fundación de la Cooperativa 12 de Octubre', 1947, 'algunaimagen.jpg', '', '', 'Se creó la Cooperativa 12 de Octubre, una institución basada en los principios de ayuda mutua y trabajo comunitario.', 'Se creó la Cooperativa 12 de Octubre, una institución basada en los principios de ayuda mutua y trabajo comunitario. En el rubro alimenticio, las primeras en ofrecer el sistema de autoservicio fueron las cooperativas de consumo, con precios más accesibles que los almacenes barriales. Entre ellas se destacó la Cooperativa 12 de Octubre, fundada en 1947 con 400 socios y un capital inicial de 133.500 pesos. Su aparición marcó el inicio de uno de los comercios más emblemáticos de Cipolletti, símbolo de trabajo comunitario y solidaridad.'),
('Raúl Quadrini obtiene su título de médico', 1947, 'algunaimagen.jpg', '', '', 'Raúl Quadrini finalizó sus estudios universitarios y obtuvo el título de médico.', 'Raúl Quadrini finalizó sus estudios universitarios y obtuvo el título de médico. Se recibió de médico el 12 de diciembre de 1947. Posteriormente desarrolló una extensa trayectoria profesional en Cipolletti, convirtiéndose en una referencia dentro del ámbito sanitario local.'),
('Radicación definitiva de Raúl Quadrini en Cipolletti', 1949, 'algunaimagen.jpg', '', '', 'Raúl Quadrini se instaló de manera permanente en la ciudad', 'Raúl Quadrini se instaló de manera permanente en la ciudad para ejercer la medicina. El y su esposa se casaron el 2 de octubre de 1949 y dos semanas después se radicaron en Cipolletti. Le ofrecieron un puesto como director en el Consello o la posibilidad de ser médico de planta en la Sala de Primeros Auxilios de Cipolletti. Eligió esta última opción. Su sueldo inicial era de 300 pesos, de los cuales 260 se destinaban al alquiler de un departamento en la calle San Martín, casi esquina Miguel Muñoz. Allí vivió varios años, instalando su consultorio en la mayor parte del departamento'),
('Mayor actividad del Círculo Italiano', 1950, 'algunaimagen.jpg', '', '', 'Durante estas dos décadas el Círculo Italiano atravesó una etapa de gran crecimiento institucional.', 'Durante estas dos décadas el Círculo Italiano atravesó una etapa de gran crecimiento institucional. La entidad se convirtió en uno de los principales espacios de reunión de la colectividad italiana de Cipolletti, organizando actividades sociales, culturales y recreativas. Además de preservar las tradiciones de los inmigrantes y sus descendientes, contribuyó al fortalecimiento de la vida comunitaria de la ciudad.'),
('Nuevo terreno para la Escuela Nº 53', 1952, 'algunaimagen.jpg', '', '', 'Se destinó un nuevo terreno para la Escuela Nº 53', 'Se destinó un nuevo terreno para la Escuela Nº 53 Bernardino Rivadavia debido al crecimiento de la matrícula escolar. La expansión de la institución reflejaba el aumento de la población y la necesidad de contar con mayores espacios educativos para atender a los estudiantes de la ciudad.'),
('Aparición de la revista Mi Valle', 1953, 'algunaimagen.jpg', '', '', 'Comenzó a publicarse la revista Mi Valle', 'Comenzó a publicarse la revista Mi Valle un medio que difundía noticias, información social y acontecimientos de interés para los habitantes de la región. La publicación contribuyó a fortalecer la identidad regional y a registrar numerosos hechos históricos y culturales del Alto Valle. Se editó hasta 1958.'),
('Fundación de la Asociación Chilena Bernardo O''Higgins', 1954, 'algunaimagen.jpg', '', '', 'La comunidad chilena fundó esta institución con el propósito de preservar sus costumbres,', 'La comunidad chilena fundó esta institución con el propósito de preservar sus costumbres, promover actividades culturales y brindar apoyo a sus integrantes. Los inmigrantes chilenos tuvieron una importante participación en el desarrollo económico y social de Cipolletti, especialmente en actividades agrícolas y comerciales. El 23 de mayo de 1954, a las 16 horas, se reunieron en la casa del señor Otto Subert los vecinos Luis Zeis, Ramiro Quezada, Raúl Jara, Pedro Pincheira y el dueño de casa, con el propósito de formar una colectividad chilena social y deportiva. Posteriormente, el 30 de mayo del mismo año, en la casa del señor Carlos Weisser, se constituyó formalmente la asociación.'),
('Reconocimiento de Alberto Jordán como propietario de Isla Jordán', 1955, 'algunaimagen.jpg', '', '', 'La Corte Suprema de Justicia reconoció oficialmente los derechos de propiedad de Alberto Jordán', 'La Corte Suprema de Justicia reconoció oficialmente los derechos de propiedad de Alberto Jordán sobre la isla que lleva su nombre. Este acontecimiento puso fin a disputas legales relacionadas con la posesión de esas tierras y consolidó el vínculo histórico entre Jordán y uno de los espacios más emblemáticos de Cipolletti.'),
('Compra del terreno de la Asociación Chilena', 1955, 'algunaimagen.jpg', '', '', 'La Asociación Chilena Bernardo O''Higgins adquirió un terreno propio para desarrollar sus actividades institucionales.', 'La Asociación Chilena Bernardo O''Higgins adquirió un terreno propio para desarrollar sus actividades institucionales. Las reuniones se realizaban en las casas de los socios. Uno de los primeros objetivos fue la compra de un terreno céntrico, que se concretó en julio de 1955 gracias a beneficios, donaciones y préstamos de los propios miembros. Los trabajos comenzaron en agosto de ese año, con aporte de mano de obra y esfuerzo económico de sus asociados'),
('Inauguración del Colegio Manuel Belgrano', 1958, 'algunaimagen.jpg', '', '', 'Se inauguró oficialmente el Colegio Manuel Belgrano,', 'Se inauguró oficialmente el Colegio Manuel Belgrano, una de las instituciones educativas más importantes de Cipolletti. El Colegio Manuel Belgrano de Cipolletti (CEM 89) nació gracias a la iniciativa del vecino Alfredo Ferrera, quien promovió la creación de un colegio secundario en la ciudad. La Comisión Pro Colegio Secundario, presidida por Aniceto Carod, trabajó incansablemente hasta la inauguración del establecimiento el 23 de marzo de 1958. El colegio comenzó a funcionar el lunes 24 de marzo de 1958, con un equipo de profesores y personal directivo que trabajaron ad honorem hasta que se oficializó la institución. El decreto provincial N° 349 del 29 de abril de 1958 nombró a Carlos R. Raggio como rector y profesor de castellano y literatura.'),
('Llegada de la Compañía Forestadora del Limay', 1959, 'algunaimagen.jpg', '', '', 'La empresa adquirió extensas propiedades en la región e impulsó actividades productivas', 'La empresa adquirió extensas propiedades en la región e impulsó actividades productivas relacionadas con el aprovechamiento de recursos forestales. El 12 de junio de 1959, la Compañía Forestadora del Limay, con domicilio en Humberto Primo 625 de la Capital Federal, compró la propiedad de Fernández Moreno. Allí apareció un personaje que aún sigue dando que hablar: el mítico doctor Lembeye. Para algunos, fue el impulsor de la colonización del sector en una época en que nadie apostaba un céntimo; para otros, un señor feudal, caprichoso y arbitrario, que reducía a sus peones a la condición de siervos de la gleba, como en la Edad Media'),
('Finalización de la sede de la Sociedad Israelita', 1960, 'algunaimagen.jpg', '', '', 'La colectividad judía culminó la construcción de su sede institucional.', 'La colectividad judía culminó la construcción de su sede institucional. En 1960 se concluyó la construcción de la sede en la calle Yrigoyen (actual ubicación). Veinte años más tarde se anexó la construcción de calle Belgrano. El edificio permitió desarrollar actividades religiosas, educativas y culturales, fortaleciendo la presencia de esta comunidad dentro de la vida social cipoleña.'),
('Fallecimiento de Alberto Jordán', 1962, 'algunaimagen.jpg', '', '', 'Murió Alberto Jordán, figura histórica estrechamente vinculada a la isla que lleva su nombre.', 'Murió Alberto Jordán, figura histórica estrechamente vinculada a la isla que lleva su nombre. Su historia quedó asociada al poblamiento y aprovechamiento productivo de una de las zonas más características de Cipolletti.'),
('Creación de la Comisión Cooperadora del Colegio Belgrano', 1962, 'algunaimagen.jpg', '', '', 'La comisión "Damas Cooperadoras Colegio Secundario Manuel Belgrano" se fundó el 17 de septiembre de 1962', 'La comisión "Damas Cooperadoras Colegio Secundario Manuel Belgrano" se fundó el 17 de septiembre de 1962 con Nidia A C de Lozano como presidenta. Estas organizaciones cumplían un papel fundamental al canalizar la participación de padres y vecinos en la mejora de las instituciones educativas.'),
('Fallecimiento del Dr. Carlos Reyna', 1967, 'algunaimagen.jpg', '', '', 'Falleció el doctor Carlos Reyna', 'Falleció el doctor Carlos Reyna considerado una de las personalidades más importantes de los primeros años de Cipolletti. Además de su labor médica, participó activamente en la primera Comisión de Fomento y contribuyó al desarrollo institucional y sanitario de la ciudad.'),
('Llegada de Miguel Barbeito', 1960, 'algunaimagen.jpg', '', '', 'El artista Miguel Barbeito llegó a Cipolletti y desarrolló una destacada trayectoria vinculada al arte y la cultura local.', 'El artista Miguel Barbeito llegó a Cipolletti y desarrolló una destacada trayectoria vinculada al arte y la cultura local. Su trabajo tendría una influencia importante en proyectos culturales y educativos de las décadas siguientes.'),
('Aparición de los primeros locales nocturnos', 1960, 'algunaimagen.jpg', '', '', 'Estas boîtes o locales nocturnos se transformaron en lugares emblemáticos', 'Estas boîtes o locales nocturnos se transformaron en lugares emblemáticos de la vida social y recreativa de Cipolletti. Las boites tuvieron su apogeo en los años ’60, con locales como Mogambo y Le Nuit. De los bailes de salón en los clubes y los asaltos en casas particulares bajo la mirada de los padres, surgieron los espacios juveniles. En Cipolletti, uno de los primeros fue Tarkus Café Concert (1974), seguido por Zakoga, inaugurado en 1978 sobre la Ruta 22, cerca de la caminera. También existió Piunk, anterior a los años ’70, que ofrecía tertulias vespertinas para estudiantes y noches de música en pleno centro.'),
('Creación de la Escuela Municipal de Cerámica', 1970, 'algunaimagen.jpg', '', '', 'Miguel Barbeito impulsó la creación de la Escuela Municipal de Cerámica', 'Miguel Barbeito impulsó la creación de la Escuela Municipal de Cerámica un espacio destinado a la formación artística y al desarrollo de nuevas expresiones culturales. La institución permitió que numerosos alumnos se acercaran al arte y adquirieran conocimientos especializados.'),
('Aparición de Tribuna Libre', 1972, 'algunaimagen.jpg', '', '', 'En 1972 se creó un nuevo periódico quincenal, denominado Tribuna Libre', 'En 1972 se creó un nuevo periódico quincenal, denominado Tribuna Libre que duró hasta mediados de 1973. Su administración estaba en San Martín y Belgrano (planta alta), con impresión en General Roca, dirigido por Abraham Thome. Era una publicación quincenal independiente, con preocupación por los problemas generales de la zona.'),
('Club Cipolletti en el Campeonato Nacional', 1973, 'algunaimagen.jpg', '', '', 'El Club Cipolletti participó en el Campeonato Nacional de Primera División', 'El Club Cipolletti participó en el Campeonato Nacional de Primera División enfrentando a algunos de los equipos más importantes del país. Este logro representó uno de los hitos deportivos más relevantes de la historia local y permitió proyectar el nombre de la ciudad a nivel nacional.'),
('Instalación del puesto de Caminera sobre Ruta 22', 1973, 'algunaimagen.jpg', '', '', 'Se habilitó un puesto de control policial sobre la Ruta Nacional 22', 'Se habilitó un puesto de control policial sobre la Ruta Nacional 22 con el objetivo de mejorar la seguridad vial y controlar la circulación vehicular en una vía cada vez más transitada debido al crecimiento regional.'),
('Aparición de Tarkus Café Concert', 1974, 'algunaimagen.jpg', '', '', 'Se inauguró Tarkus Café Concert, un espacio cultural y recreativo donde se desarrollaban espectáculos artísticos, musicales y teatrales', 'Se inauguró Tarkus Café Concert, un espacio cultural y recreativo donde se desarrollaban espectáculos artísticos, musicales y teatrales . El lugar se convirtió en un importante punto de encuentro para la actividad cultural cipoleña.'),
('La Colmena adherida a FACA', 1974, 'algunaimagen.jpg', '', '', 'La cooperativa La Colmena se integró a la Federación Argentina de Cooperativas Agropecuarias (FACA).Con el objetivo de lograr una mayor presencia en el mercado interno, se estableció en Buenos Aires el socio José Luis Albanesi, encargado de la comercialización en distintos mercados de esa ciudad.', 'La cooperativa La Colmena se integró a la Federación Argentina de Cooperativas Agropecuarias (FACA).Con el objetivo de lograr una mayor presencia en el mercado interno, se estableció en Buenos Aires el socio José Luis Albanesi, encargado de la comercialización en distintos mercados de esa ciudad. La cooperativa contaba con un puesto propio en el antiguo Mercado del Abasto. En 1975, en una etapa de expansión, la entidad adquirió un predio de más de dos hectáreas sobre la Ruta Nacional 22, con el propósito de construir un frigorífico moderno y luego una planta de empaque. En agosto de 1977 se inició la construcción de la nueva planta, con una superficie cubierta de 2.550 metros cuadrados, equipada con moderna maquinaria de lavado, tratamiento, secado, selección y clasificación de fruta, lo que permitía procesar alrededor de 3.000 cajones diarios. Durante el período 1974–1991, La Colmena estuvo adherida a la Federación Argentina de Cooperativas Agrarias (FACA), participando activamente en la misma.'),
('Victoria histórica frente a Boca Juniors', 1977, 'algunaimagen.jpg', '', '', 'El Club Cipolletti derrotó a Boca Juniors por 4 a 2', 'El Club Cipolletti derrotó a Boca Juniors por 4 a 2 en uno de los encuentros más recordados de la historia deportiva local. El triunfo frente a uno de los clubes más importantes de Argentina generó orgullo en toda la comunidad y quedó grabado en la memoria colectiva de la ciudad.'),
('Inauguración de Zakoga', 1978, 'algunaimagen.jpg', '', '', 'Zakoga inaugurado en 1978 sobre la Ruta 22', 'Zakoga inaugurado en 1978 sobre la Ruta 22 cerca de la caminera, un nuevo espacio de recreación y encuentro social que alcanzó gran popularidad durante aquellos años. Formó parte de la intensa vida nocturna y cultural que caracterizó a Cipolletti durante las décadas de 1970 y 1980.'),
('Pérdida de la cosecha en Bodega La Falda', 1978, 'algunaimagen.jpg', '', '', 'Heladas y granizo afectaron severamente la producción de la Bodega La Falda,', 'Heladas y granizo afectaron severamente la producción de la Bodega La Falda, provocando importantes pérdidas económicas. Originalmente, el establecimiento contaba con 150 hectáreas y una capacidad de producción de un millón de litros de vino. Tuvo actividad plena hasta fines de la década de 1970, cuando perdió las cosechas de 1978, 1980 y 1981 a causa de heladas y granizo. Este hecho puso de manifiesto la vulnerabilidad de la actividad agrícola y vitivinícola frente a los fenómenos climáticos.'),
('Obtención de la personería jurídica de la Sociedad Israelita', 1980, 'algunaimagen.jpg', '', '', 'La Sociedad Israelita obtuvo reconocimiento legal formal, el 20 de febrero de 1980', 'La Sociedad Israelita obtuvo reconocimiento legal formal, el 20 de febrero de 1980 mediante su personería jurídica. Los oficios religiosos y actividades sociales, culturales y deportivas se realizan en esta sede, manteniendo vínculos de amistad con todas las organizaciones de la ciudad. Allí funciona también la Escuela Municipal de Judo. La Sociedad Israelita participó en la elaboración del Plan Estratégico de Cipolletti y es miembro del Consejo de Seguridad Ciudadana. A través del Kinder Club, los niños aprenden valores judíos y universales mediante el juego, la música, los bailes, la historia y el idioma hebreo. Bajo el lema “Shalom y Tikvá” —Paz y Esperanza—, continúan el camino trazado por los pioneros que desafiaron al desierto y, junto a otros, fueron artífices de la Patagonia'),
('Traslado del correo a Mengelle y Teniente Ibáñez', 1980, 'algunaimagen.jpg', '', '', 'El servicio postal se trasladó a un nuevo edificio ubicado en la esquina de Mengelle y Teniente Ibáñez, donde pertenece hasta hoy.', 'El servicio postal se trasladó a un nuevo edificio ubicado en la esquina de Mengelle y Teniente Ibáñez, donde pertenece hasta hoy. La mudanza respondió a la necesidad de contar con instalaciones más adecuadas para atender a una población en crecimiento.'),
('Inauguración de la Sala Saulo Benavente', 1983, 'algunaimagen.jpg', '', '', 'La primera sala de exposiciones de Cipolletti fue inaugurada en 1983.', 'La primera sala de exposiciones de Cipolletti fue inaugurada en 1983. Desde entonces, los artistas de la ciudad y de la región contaron con un espacio propio para presentar sus obras. El libro la señala como un hito en el desarrollo de la actividad artística local.'),
('David Luis Ferracuti preside la Federación Nacional de Cooperativas', 1989, 'algunaimagen.jpg', '', '', 'En 1989 David Luis Ferracuti ocupó la presidencia de la Federación Nacional de Cooperativas.', 'En 1989 David Luis Ferracuti ocupó la presidencia de la Federación Nacional de Cooperativas. En 1989 David Luis Ferracuti, integrante de la Cooperativa La Colmena, ocupó la presidencia de la Federación Nacional de Cooperativas. Fue el primer y único representante de la actividad frutícola en ocupar ese cargo, que hasta entonces había estado tradicionalmente en manos de representantes del sector cerealero.'),
('Finaliza la adhesión de La Colmena a FACA', 1991, 'algunaimagen.jpg', '', '', 'La Colmena estuvo adherida a la Federación Argentina de Cooperativas Agrarias (FACA) durante el período 1974–1991.', 'La Colmena estuvo adherida a la Federación Argentina de Cooperativas Agrarias (FACA) durante el período 1974–1991. El cierre de esta etapa forma parte de la historia del cooperativismo cipoleño, un motor importante del crecimiento productivo regional.'),
('Reconocimiento oficial de la Escuela Dante Alighieri', 1992, 'algunaimagen.jpg', '', '', 'En 1992 la Escuela Dante Alighieri fue reconocida oficialmente en Roma', 'En 1992 la Escuela Dante Alighieri fue reconocida oficialmente en Roma . Se instaló en Cipolletti gracias a la comisión del Círculo. Entre sus gestores estuvieron Luis Fedeli e Ida de Anna. Primero se dictaron clases en un salón del primer piso; luego, con el crecimiento, se construyeron aulas sobre calle Sáenz Peña. Se ofrecían cursos para adultos, niños, jardín de infantes e informática en italiano. Su directora y docente en algunos cursos fue Valeria Varoli.'),
('Comienza la restauración de la Bodega La Falda', 1994, 'algunaimagen.jpg', '', '', 'En 1994 Jorge Hercig, nieto del fundador de la Bodega La Falda, comenzó la restauración del establecimiento', 'En 1994 Jorge Hercig, nieto del fundador de la Bodega La Falda, comenzó la restauración del establecimiento . La reconstrucción se realizó pieza por pieza y con esfuerzo propio. Para entonces la vitivinicultura había cambiado, pasando de priorizar la cantidad a valorar cada vez más la calidad del producto.'),
('Ascenso del Club Cipolletti', 1995, 'algunaimagen.jpg', '', '', 'En la temporada 1995/96 el Club Cipolletti logró el ascenso al Torneo Argentino A y posteriormente llegó a la Primera B Nacional.', 'En la temporada 1995/96 el Club Cipolletti logró el ascenso al Torneo Argentino A y posteriormente llegó a la Primera B Nacional. Este logro marcó la recuperación deportiva del club después de su descenso de la segunda división en 1990/91.'),
('Participación en la Primera B Nacional', 1996, 'algunaimagen.jpg', '', '', 'El Club Cipolletti participó en la Primera B Nacional desde la temporada 1996/97 hasta 2000/01', 'El Club Cipolletti participó en la Primera B Nacional desde la temporada 1996/97 hasta 2000/01 . Durante este período volvió a competir en una de las principales categorías del fútbol argentino y proyectó nuevamente el nombre de la ciudad en el ámbito deportivo nacional.'),
('El Club de Jardinería Maipue se hace cargo del Parque Rosauer', 2000, 'algunaimagen.jpg', '', '', 'En el año 2000 el Club de Jardinería Maipue se hizo cargo del Parque Don Juan Erich Rosauer', 'En el año 2000 el Club de Jardinería Maipue se hizo cargo del Parque Don Juan Erich Rosauer mediante un comodato por 15 años. La recuperación y mejora del espacio se realizó en colaboración con la Municipalidad de Cipolletti. El parque incorporó y mantuvo espacios recreativos como rosedal, juegos infantiles, sector de patinaje y circuito aeróbico.'),
('Finaliza la etapa de Tiempo Cipoleño', 2001, 'algunaimagen.jpg', '', '', 'El periódico Tiempo Cipoleño, surgido a mediados de 1977, continuó acompañando la vida de la ciudad hasta 2001.', 'El periódico Tiempo Cipoleño, surgido a mediados de 1977, continuó acompañando la vida de la ciudad hasta 2001. Según el libro, fue editado por Herman Avoscan, Héctor Vidal Do Santos y Hugo Laurent y se caracterizó por informar y opinar sobre la vida local con originalidad.'),
('Comienza a funcionar el IUNA en Cipolletti', 2001, 'algunaimagen.jpg', '', '', 'En 2001 comenzó a funcionar en Cipolletti el Instituto Universitario Nacional de Arte (IUNA)', 'En 2001 comenzó a funcionar en Cipolletti el Instituto Universitario Nacional de Arte (IUNA) a partir de un convenio entre la Municipalidad y la Universidad Nacional del Comahue. El espacio permitió que alumnos de toda la Patagonia accedieran a formación artística y amplió la presencia de instituciones culturales y educativas en la ciudad.'),
('Cipolletti cumple 100 años', 2003, 'algunaimagen.jpg', '', '', 'Al cumplirse el centenario de la ciudad, en 2003, el Registro Civil registró 434 nacimientos, 102 matrimonios y 162 defunciones durante ese año.', 'Al cumplirse el centenario de la ciudad, en 2003, el Registro Civil registró 434 nacimientos, 102 matrimonios y 162 defunciones durante ese año. Los acumulados desde 1993: 15.498 nacimientos, 2.833 matrimonios y 4.325 defunciones. Estos datos permiten observar el crecimiento demográfico de Cipolletti a lo largo del siglo.'),
('Descenso del Club Cipolletti al Torneo Argentino B', 2005, 'algunaimagen.jpg', '', '', 'En la temporada 2005/06 el Club Cipolletti descendió al Torneo Argentino B.', 'En la temporada 2005/06 el Club Cipolletti descendió al Torneo Argentino B. Este descenso fue seguido por una rápida recuperación deportiva y constituye una de las etapas de la trayectoria del club que el libro presenta hasta su regreso al Torneo Argentino A.'),
('La Bodega La Falda se incorpora a la Ruta del Vino de Río Negro', 2006, 'algunaimagen.jpg', '', '', 'Desde 2006 la Bodega-Museo La Falda forma parte de la Asociación Civil Ruta del Vino de Río Negro', 'Desde 2006 la Bodega-Museo La Falda forma parte de la Asociación Civil Ruta del Vino de Río Negro junto con otras bodegas de la región. La asociación busca incentivar la actividad vitivinícola y el turismo enológico mediante cursos, capacitaciones, actividades culturales y conciertos con fines benéficos.'),
('El Club Cipolletti vuelve a consagrarse campeón', 2006, 'algunaimagen.jpg', '', '', 'Después del descenso al Torneo Argentino B en 2005/06, el Club Cipolletti se consagró campeón', 'Después del descenso al Torneo Argentino B en 2005/06, el Club Cipolletti se consagró campeón en la temporada 2006/07 y logró regresar al Torneo Argentino A. El resultado reafirmó la importancia histórica del club dentro del fútbol regional y nacional.'),
('La Escuela Rural La Falda cumple 75 años', 2009, 'algunaimagen.jpg', '', '', 'La Escuela Rural La Falda cumplió 75 años', 'La Escuela Rural La Falda cumplió 75 años en 2009. La familia Hercig, que donó terrenos al Consejo Nacional de Educación y construyó las primeras aulas. La institución nació para atender las necesidades educativas de las familias vinculadas a la zona rural.'),
('La Bodega La Falda proyecta un salón de eventos', 2010, 'algunaimagen.jpg', '', '', 'Jorge Hercig anunció la inauguración de un salón especialmente acondicionado para recibir actividades vinculadas con la música clásica y el vino,', 'Jorge Hercig anunció la inauguración de un salón especialmente acondicionado para recibir actividades vinculadas con la música clásica y el vino, En una entrevista publicada el 3 de octubre de 2010, Jorge Hercig anunció la inauguración de un salón especialmente acondicionado para recibir actividades vinculadas con la música clásica y el vino, con capacidad aproximada para 60 personas. El primer concierto realizado en la bodega fue a beneficio de la Escuela Rural La Falda.'),
('Robo del equipamiento de Conectar Igualdad en la Escuela Nº 53', 2016, 'algunaimagen.jpg', '', '', 'En 2016 la Escuela Nº 53 sufrió el robo del equipamiento correspondiente al Plan Conectar Igualdad.', 'En 2016 la Escuela Nº 53 sufrió el robo del equipamiento correspondiente al Plan Conectar Igualdad. La institución continúa sin servicio de internet y sin equipamiento audiovisual, a pesar de su importante matrícula. El episodio forma parte de las dificultades materiales que acompañan la historia reciente de la escuela.'),
('La Sociedad Española recibe un predio en Isla Jordán', 2017, 'algunaimagen.jpg', '', '', 'En 2017 la Municipalidad de Cipolletti cedió a la Sociedad Española un predio en la Isla Jordán', 'En 2017 la Municipalidad de Cipolletti cedió a la Sociedad Española un predio en la Isla Jordán . La institución realizó el cierre perimetral, instaló un portón de acceso, niveló el suelo y presentó proyectos para continuar construyendo un espacio recreativo destinado a socios y vecinos.'),
('Origen de la columna Ecos de la Historia', 2023, 'algunaimagen.jpg', '', '', 'El proyecto Ecos de la Historia tuvo su origen en 2023', 'El proyecto Ecos de la Historia tuvo su origen en 2023 . La columna comenzó a difundir contenidos sobre la historia local a través de la radio y el diario, recuperando investigaciones, documentos, entrevistas y relatos de microhistoria. Su objetivo fue acercar el pasado de Cipolletti a las nuevas generaciones y fortalecer la identidad local.'),
('Cipolletti del hoy: economía, servicios, educación y cultura', 2025, 'algunaimagen.jpg', '', '', 'Cipolletti en 2025 una ciudad clave del Alto Valle,', 'Cipolletti en 2025 una ciudad clave del Alto Valle, históricamente ligada a la fruticultura pero con una economía diversificada. Se destaca la agricultura, la industria y la construcción, un parque industrial en expansión, los servicios y el comercio, además de la salud y la educación. Con presencia de universidades y una infraestructura sanitaria de alto nivel.'),
('Ecos de la Historia continúa en radio y medios gráficos', 2025, 'algunaimagen.jpg', '', '', 'En 2025 la columna Ecos de la Historia se emitía los sábados', 'En 2025 la columna Ecos de la Historia se emitía los sábados de 11:30 a 12:00 por LU19 FM 690. El proyecto continuaba articulando radio, publicaciones gráficas e investigación histórica con el propósito de que las nuevas generaciones conozcan el pasado, comprendan el presente y proyecten el futuro construyendo identidad cipoleña.'),
('Cipolletti en el presente', 2026, 'algunaimagen.jpg', '', '', 'Cipolletti, una ciudad de aproximadamente 5.257 km² de jurisdicción municipal,', 'Cipolletti, una ciudad de aproximadamente 5.257 km² de jurisdicción municipal, integrada al Alto Valle y vinculada a la confluencia de los ríos Limay y Neuquén. La fruticultura sigue siendo relevante, pero convive con actividades industriales, construcción, comercio, servicios, petróleo, salud y educación. Se destaca por la expansión urbana y la transformación de antiguas zonas rurales en áreas residenciales.');



CREATE TABLE formulario(
	nombre VARCHAR(100) NOT NULL,
	mail VARCHAR(150) NOT NULL,
	comentario TEXT,
	enviado TIMESTAMP
);

CREATE TABLE usuarios(
	id INT PRIMARY KEY AUTO_INCREMENT,
	nombre VARCHAR(100) NOT NULL,
	email VARCHAR(100) UNIQUE NOT NULL,
	contraseña VARCHAR(255) NOT NULL,
	rol ENUM("user","admin") NOT NULL,
	token TEXT NULL,
	creado TIMESTAMP NOT NULL
);

CREATE TABLE productos(
	id INT PRIMARY KEY AUTO_INCREMENT,
	nombre VARCHAR(100),
	descripcion TEXT,
	precio DECIMAL(10,2),
	imagen VARCHAR(255),
	creado TIMESTAMP NOT NULL
);

CREATE TABLE carrito(
	id_carrito INT PRIMARY KEY AUTO_INCREMENT,
	id_usuario INT,
	FOREIGN KEY (id_usuario) REFERENCES usuarios(id),
	estado ENUM("abierto", "cerrado")
);

CREATE TABLE detalles_carrito(
	id_detalle INT PRIMARY KEY AUTO_INCREMENT,
	id_carrito INT,
	FOREIGN KEY (id_carrito) REFERENCES carrito(id_carrito),
	id_producto INT,
	FOREIGN KEY (id_producto) REFERENCES productos(id),
	cantidad INT,
	precio_unitario DECIMAL(10,2) NOT NULL
);



CREATE TABLE compras(
	id_compra INT PRIMARY KEY AUTO_INCREMENT,
	id_usuario INT,
	FOREIGN KEY (id_usuario) REFERENCES usuarios(id),
	total DECIMAL(10,2),
	fecha TIMESTAMP
);

CREATE TABLE detalles_compras(
	id_detalle INT PRIMARY KEY AUTO_INCREMENT,
	id_compra INT,
	FOREIGN KEY (id_compra) REFERENCES compras(id_compra),
	id_producto INT,
	cantidad INT,
	precio_unitario DECIMAL(10,2),
	subtotal DECIMAL(10,2)
);

CREATE TABLE tickets(
	id_ticket INT PRIMARY KEY AUTO_INCREMENT,
	numero_ticket VARCHAR(20) UNIQUE,
	id_compra INT,
	FOREIGN KEY (id_compra) REFERENCES compras(id_compra),
	pdf_path VARCHAR(255),
	fecha TIMESTAMP
); 


CREATE TABLE favoritos(
	id_favorito INT PRIMARY KEY AUTO_INCREMENT,
	id_usuario INT,
	FOREIGN KEY (id_usuario) REFERENCES usuarios(id_usuario),
	id_evento INT,
	FOREIGN KEY (id_evento) REFERENCES eventos(id_evento)
	);
